style.css:
@-moz-document domain("ebay.com") {
/* ======================================================================
     TOKENS
     Every color/opacity decision in this file reads from these variables.
     Change the theme by editing this block only.
     ====================================================================== */
  html {
    /* ink */
    --hg-ink: #d7e6da;            /* primary text */
    --hg-ink-dim: #9fb3a3;        /* secondary/muted text */
    --hg-ink-bright: #eaffee;     /* headings, emphasis on dark glass */

    /* accent green, light -> dark */
    --hg-accent-soft: #72f59a;    /* default links, icons */
    --hg-accent: #65ff94;         /* active borders, dividers, focus */
    --hg-accent-strong: #a5ffb8;  /* hover text / strongest highlight */
    --hg-accent-cta: #226b3b;     /* solid filled buttons (submit, buy) */
    --hg-accent-cta-hover: #2c884a;

    /* surfaces: 3 tiers only.
       surface-0/1 are transparent so the grid wallpaper shows through
       every panel that used to be a flat fill (cards, header, footer,
       filters, tabs, etc). surface-2 stays a faint tint, only for form
       fields, so typed text has a hint of a field to sit in. */
    --hg-surface-0: transparent;  /* page canvas */
    --hg-surface-1: transparent;  /* raised panel: cards, header, footer */
    --hg-surface-2: rgba(16,27,20,.55); /* form fields / inputs, slightly inset */

    /* glass overlay (dropdowns, popovers, modals, VI-EVO banners) */
    --hg-glass-bg: linear-gradient(135deg, rgba(21,62,37,.80), rgba(6,25,15,.92));
    --hg-glass-blur: blur(14px) saturate(130%);

    /* borders: 2 tiers only */
    --hg-border-resting: #365a3d;     /* structural, always-on dividers */
    --hg-border-active: var(--hg-accent); /* hover/focus/selected only */

    /* glow: one strength, reused, not stacked differently per rule */
    --hg-glow-sm: 0 0 8px rgba(101,255,148,.30);
    --hg-glow-md: 0 0 14px rgba(101,255,148,.42);
    --hg-glow-lg: 0 0 22px rgba(101,255,148,.30);

    --hg-focus-ring: 0 0 0 2px rgba(101,255,148,.55);
  }

  /* ======================================================================
     BASE CANVAS + SIGNATURE GRID WALLPAPER
     Boosted slightly vs v1.12 so it's visible, not just technically present.
     ====================================================================== */
  /* PERFORMANCE NOTE (scroll smoothness):
     background-attachment: fixed on html/body is the classic cause of
     choppy scrolling — on most engines a fixed background has to be
     repainted against the new scroll position on every single frame,
     because it lives on the same layer as the content that's scrolling.
     The fix below keeps the exact same visual (same colors, same grid,
     same "stays put while content scrolls" behavior) but moves the grid
     onto its own dedicated position:fixed element instead. A position:
     fixed element gets its own GPU compositing layer automatically, so
     the browser can cache it once and just scroll the content on top of
     it, instead of repainting the gradient itself on every scroll tick.
     html/body keep a cheap flat color only (in case the pseudo-element
     ends up hidden by something — e.g. an ancestor with its own CSS
     transform, which is the one case that can make position:fixed stop
     being relative to the viewport). */
  html, body {
    background-color: #0a0a0a !important;
    background-image: none !important;
    min-height: 100vh !important;
  }
  html::before {
    content: "" !important;
    position: fixed !important;
    inset: 0 !important;
    z-index: 0 !important;
    pointer-events: none !important;
    background-color: #0a0a0a !important;
    background-image:
      linear-gradient(to right, rgba(146,255,174,.14) 1px, transparent 1px),
      linear-gradient(to bottom, rgba(146,255,174,.14) 1px, transparent 1px),
      linear-gradient(to bottom, rgba(110,239,143,.035) 1px, transparent 1px) !important;
    background-size: 40px 40px, 40px 40px, 100% 4px !important;
    background-position: 0 0, 0 0, 0 0 !important;
    background-repeat: repeat, repeat, repeat !important;
    /* Promotes this to its own compositor layer instead of repainting
       with the page; transform/backface-visibility are the standard
       pair browsers key this optimization off of. */
    transform: translateZ(0) !important;
    backface-visibility: hidden !important;
    will-change: transform !important;
  }

  html, body, #mainContent, #maincontent, main, [role="main"] {
    color: var(--hg-ink) !important;
  }
  /* Everything between body and the actual content panels stays clear so
     the grid painted above keeps showing through the gutters. Explicit
     z-index/position so these panels paint above the fixed grid layer. */
  #mainContent, #maincontent, main, [role="main"] {
    position: relative !important;
    z-index: 1 !important;
    background-color: transparent !important;
    background-image: none !important;
  }

  /* Outer layout shells stay transparent so the grid reads through the
     gutters; only actual content panels (below) get a solid fill. */
  html body .page-grid,
  html body .page-layout,
  html body .page-grid-container,
  html body #mainContent > div,
  html body #maincontent > div,
  html body main > div,
  html body [role="main"] > div,
  html body section.custom-page-grid-container,
  html body .custom-page-grid-container,
  html body #mainContent > section,
  html body #mainContent > div > section,
  html body main > section,
  html body main > div > section,
  html body [role="main"] > section,
  html body .page-grid-container > section,
  html body .page-grid-container > div[class*="bg-neutral"],
  html body [class*="homepage"] > section,
  html body [class*="homepage"] > div[class*="bg-neutral"],
  html body main section[class*="bg-neutral"],
  html body main div[class*="bg-neutral"][class*="hp-"],
  html body #mainContent div[class*="bg-neutral"][class*="hp-"],
  html body main > div[class*="bg-neutral"],
  html body main > div > div[class*="bg-neutral"],
  html body #mainContent > div[class*="bg-neutral"],
  html body #mainContent > div > div[class*="bg-neutral"],
  html body [role="main"] > div[class*="bg-neutral"],
  html body.vi-body .vi-evo,
  html body.vi-body .vi-evo > main,
  html body.vi-body .vi-evo .main-container,
  html body.vi-body .vi-evo .x-vi-evo-main-container,
  html body.vi-body .vi-evo .top-panel-container,
  html body.vi-body .vi-evo .bottom-panel-container,
  html body.vi-body #vi-global-header.vi-global-header.vi-grid,
  html body.vi-body #vi-global-header.vi-global-header > .ghw.ghw--loaded,
  html body.vi-body #vi-global-header.vi-global-header > .ghw.ghw--loaded > header#gh.gh-header {
    background: transparent !important;
    background-color: transparent !important;
    background-image: none !important;
  }

  /* ----------------------------------------------------------------------
     SAFETY NET — generated/inline white backgrounds anywhere in the page.
     eBay's homepage and search pages render a lot of their layout through
     Tailwind-style utility classes and JS-written inline styles with no
     stable name, so no fixed list of selectors ever catches all of them
     (that's why v1.1 through v1.21 kept finding new white rectangles one
     DOM snapshot at a time). This block catches the common *patterns*
     instead of individual components, and runs EARLY in the cascade: the
     specific panel/card/glass rules further down in this file (buybox,
     dropdowns, cards, inputs, the image mat) are written with selectors
     at least as specific, so they still win back a solid or glass fill
     where one is actually wanted. Everything else just goes transparent
     and the grid wallpaper shows straight through it.
     ---------------------------------------------------------------------- */
  html body [class*="bg-white"],
  html body [class~="bg-white"],
  html body [class*="bg-neutral-0"],
  html body [class*="bg-neutral-50"],
  html body [class*="bg-neutral-100"],
  html body [class*="bg-neutral-200"],
  html body [class*="bg-gray-50"],
  html body [class*="bg-gray-100"],
  html body [class*="bg-gray-200"],
  html body [style*="background-color: rgb(255, 255, 255)"],
  html body [style*="background-color:#fff"],
  html body [style*="background-color: #fff"],
  html body [style*="background-color: #ffffff"],
  html body [style*="background: rgb(255, 255, 255)"],
  html body [style*="background-color: rgb(248, 248, 248)"],
  html body [style*="background-color: rgb(247, 247, 247)"],
  html body [style*="background-color: #f8f8f8"],
  html body [style*="background-color: #f7f7f7"],
  html body [style*="background-color: #f5f5f5"] {
    background-color: transparent !important;
    background-image: none !important;
  }
  /* Generated global-header / sticky-search wrappers with hashed or
     prefix-only class names (no stable "header" or "sticky" substring). */
  html body div[class^="gh"], html body section[class^="gh"],
  html body form[class^="gh"], html body header[class^="gh"],
  html body div[class*=" gh"], html body section[class*=" gh"],
  html body div[id^="gh"], html body section[id^="gh"],
  html body div[class*="sticky"], html body div[class*="Sticky"],
  html body div[class*="header-"], html body div[class*="Header"],
  html body div[class*="search-header"], html body div[class*="searchHeader"],
  html body div[class*="search-bar"], html body div[class*="searchBar"] {
    background-color: transparent !important;
    background-image: none !important;
  }
  /* A floating toolbar whose position is set inline by script often
     carries its background the same way. */
  html body div[style*="position: fixed"][style*="top: 0"],
  html body div[style*="position:fixed"][style*="top:0"],
  html body div[style*="position: sticky"][style*="top: 0"],
  html body div[style*="position:sticky"][style*="top:0"] {
    background-color: transparent !important;
    background-image: none !important;
  }

  ::selection { background: #2c7543 !important; color: #fff !important; }

  /* ======================================================================
     TYPOGRAPHY
     ====================================================================== */
  h1, h2, h3, h4, h5, h6, p, label, legend, summary,
  dt, dd, th, td, li, small, strong, em,
  [class*="title"], [class*="Title"],
  [class*="subtitle"], [class*="description"] {
    color: var(--hg-ink) !important;
  }

  a, a:link, #gh a, footer a, nav a {
    color: var(--hg-accent-soft) !important;
    text-decoration-color: #3a8050 !important;
  }
  a:visited { color: #b0daa8 !important; }

  /* One hover rule for all links; subtle glow, not a halo + shadow stack. */
  html body a:hover, html body a:focus,
  html body [role="link"]:hover {
    color: var(--hg-accent-strong) !important;
    text-decoration-color: currentColor !important;
    text-shadow: var(--hg-glow-sm) !important;
  }

  /* ======================================================================
     FORM CONTROLS
     ====================================================================== */
  input[type="text"], input[type="search"], input[type="email"],
  input[type="password"], input[type="number"], input[type="tel"],
  textarea, select, [role="combobox"], [contenteditable="true"],
  .gh-tb, #gh-ac, #gh-cat, .textbox__control {
    background-color: var(--hg-surface-2) !important;
    color: var(--hg-ink) !important;
    border-color: #426a4c !important;
    caret-color: var(--hg-accent-soft) !important;
  }
  input::placeholder, textarea::placeholder { color: var(--hg-ink-dim) !important; opacity: 1 !important; }

  html body input[type="text"]:hover,
  html body input[type="search"]:hover,
  html body textarea:hover,
  html body [role="combobox"]:hover {
    border-color: var(--hg-accent) !important;
    box-shadow: var(--hg-glow-sm) !important;
  }

  input:focus, textarea:focus, select:focus, button:focus, a:focus, [role="button"]:focus {
    outline: 2px solid var(--hg-accent-strong) !important;
    outline-offset: 2px !important;
  }

  html body select option, html body select optgroup {
    background-color: #102719 !important;
    color: #d9ffe4 !important;
  }

  /* ======================================================================
     BUTTONS
     Plain buttons: quiet hover (border brighten only).
     The search submit / primary CTA: solid fill, reserved for real actions.
     ====================================================================== */
  button, [role="button"], .btn, .fake-btn, .ux-call-to-action,
  .filter-menu-button, .x-atc-action {
    background-color: #17241b !important;
    color: var(--hg-accent-soft) !important;
    border-color: var(--hg-border-resting) !important;
  }
  /* .fake-link / .ux-action cover the inline "See details", "Message",
     and info-icon (ⓘ) controls seen throughout the item page — these are
     link-styled, not button-styled, so they get no fill, just accent text. */
  html body .fake-link, html body .ux-action,
  html body button.fake-link, html body a.ux-action {
    background-color: transparent !important;
    color: var(--hg-accent-soft) !important;
    border-color: transparent !important;
  }
  html body .fake-link:hover, html body .ux-action:hover {
    color: var(--hg-accent-strong) !important;
    text-shadow: var(--hg-glow-sm) !important;
  }
  html body button:hover, html body [role="button"]:hover,
  html body .btn:hover, html body .fake-btn:hover,
  html body [role="tab"]:hover, html body [role="menuitem"]:hover,
  html body input[type="button"]:hover,
  html body input[type="submit"]:hover,
  html body select:hover {
    color: var(--hg-accent-strong) !important;
    border-color: var(--hg-accent) !important;
    box-shadow: var(--hg-glow-sm) !important;
  }
  html body button:hover svg,
  html body [role="button"]:hover svg,
  html body .gh-header a:hover svg,
  html body #dp-global-footer a:hover svg {
    filter: drop-shadow(0 0 4px rgba(101,255,148,.45)) !important;
  }

  #gh-btn, button[type="submit"],
  html body #gh-search-btn,
  html body section.gh-header__main.gh-header__main-sticky #gh-search-btn {
    background-color: var(--hg-accent-cta) !important;
    color: #f5fff7 !important;
    border-color: #3b9a56 !important;
  }
  html body #gh-btn:hover, html body button[type="submit"]:hover,
  html body #gh-search-btn:hover {
    background-color: var(--hg-accent-cta-hover) !important;
    border-color: var(--hg-accent-strong) !important;
    color: #fff !important;
    box-shadow: var(--hg-glow-md) !important;
  }

  /* ======================================================================
     STRUCTURAL SURFACES: header, nav, footer, drawers, modals (resting)
     ====================================================================== */
  header, footer, nav, aside, section, article,
  [role="navigation"], [role="dialog"], [role="menu"], [role="listbox"],
  [class*="drawer"], [class*="Drawer"],
  #gh, #gh-top, #gh-gb, #gh-cat, .gh-flyout, .gh-menu,
  #glbfooter, .gh-clearfix, .gh-tbl, .gh-td,
  .srp-controls, .srp-controls__row, .srp-river,
  .x-breadcrumb, .breadcrumbs, .x-item-title,
  html body #gh, html body #gh-header, html body #gh-main,
  html body #gh-f, html body #gh-gb, html body #gh-top,
  html body #gh-bar, html body #gh-ug,
  html body #global-header, html body #globalHeader,
  html body .ghw, html body .gh-header, html body .gh-header__main,
  html body .global-header, html body .globalHeader,
  html body .sticky-header, html body .stickyHeader,
  html body .header-sticky, html body .headerSticky,
  html body section.gh-header__main.gh-header__main-sticky,
  html body section.gh-header__main.gh-header__main-sticky > div.gh-header__logo-cats-wrap,
  html body section.gh-header__main.gh-header__main-sticky > form#gh-f.gh-search,
  html body #dp-global-footer, html body #dp-global-footer footer.gh-footer,
  html body #glbfooter footer.gh-footer,
  html body section.custom-page-grid-container > .dp-topo-item-grid-2x2,
  html body section.custom-page-grid-container > section.border-subtle,
  html body main .border-subtle, html body #mainContent .border-subtle,
  html body [class*="homepage"] .border-subtle,
  html body [class*="my-garage"], html body [class*="myGarage"],
  html body [class*="MyGarage"], html body [class*="garage"],
  html body [class*="Garage"], html body [id*="garage"], html body [id*="Garage"],
  html body .s-item, html body .s-item__wrapper,
  html body section.gh-header__main.gh-header__main-sticky #gh-search-box,
  html body section.gh-header__main.gh-header__main-sticky .gh-search__wrap,
  html body section.gh-header__main.gh-header__main-sticky #gh-ac-wrap,
  html body section.gh-header__main.gh-header__main-sticky #gh-ac,
  html body section.gh-header__main.gh-header__main-sticky #gh-cat,
  html body #vi-global-header #gh > nav.gh-nav,
  html body #vi-global-header #gh > section.gh-header__main {
    background-color: var(--hg-surface-1) !important;
    background-image: none !important;
    color: var(--hg-ink) !important;
    border-color: var(--hg-border-resting) !important;
  }
  /* form-field sub-cases inside the header keep the inset surface tier */
  html body section.gh-header__main.gh-header__main-sticky #gh-search-box,
  html body section.gh-header__main.gh-header__main-sticky .gh-search__wrap,
  html body section.gh-header__main.gh-header__main-sticky #gh-ac-wrap,
  html body section.gh-header__main.gh-header__main-sticky #gh-ac,
  html body section.gh-header__main.gh-header__main-sticky #gh-cat,
  html body #gh input, html body #gh-f input,
  html body header input[type="text"], html body header input[type="search"],
  html body [role="banner"] input, html body [role="search"] input,
  html body [role="banner"] select, html body #gh select {
    background-color: var(--hg-surface-2) !important;
    color: var(--hg-ink) !important;
    border-color: #426a4c !important;
  }

  /* Pseudo-element overlays some skins paint separately from the element */
  html body #gh::before, html body #gh::after,
  html body section.gh-header__main.gh-header__main-sticky::before,
  html body section.gh-header__main.gh-header__main-sticky::after {
    background-color: var(--hg-surface-1) !important;
    background-image: none !important;
  }

  html body img, html body picture, html body video,
  html body canvas, html body svg, html body iframe { filter: none !important; }

  .s-item__image-wrapper, .s-item__image, .ux-image-carousel-item,
  .ux-image-carousel-container, .gallery, .gallery__image {
    background-color: #e6e9e5 !important;
  }

  /* Modals / popovers use the glass treatment, not a flat panel */
  [class*="modal"], [class*="Modal"], [class*="popover"], [class*="Popover"] {
    background: var(--hg-glass-bg) !important;
    -webkit-backdrop-filter: var(--hg-glass-blur) !important;
    backdrop-filter: var(--hg-glass-blur) !important;
    color: var(--hg-ink-bright) !important;
    border: 1px solid rgba(101,255,148,.45) !important;
    box-shadow: var(--hg-glow-md) !important;
  }

  /* ======================================================================
     LISTING CARDS / RESULTS
     eBay has shipped more than one generation of search-result markup
     (the classic .s-item cards this theme was first built against, and a
     newer card component with different class names). Both are matched
     here so the listing page gets the same card treatment as the
     homepage regardless of which markup this account is served.
     ====================================================================== */
  .s-item__info, .s-item__details,
  .srp-river-results, .srp-rail, .srp-sidebar,
  .x-item-title, .x-price-primary, .x-about-this-item,
  .vim, .vim-container, .ux-layout-section,
  .ux-section, .ux-labels-values, .ux-layout-section__item,
  [class*="card"], [class*="Card"],
  [class*="s-card"], [class*="su-card"],
  [class*="listing-card"], [class*="ListingCard"],
  [class*="item-card"], [class*="ItemCard"] {
    background-color: var(--hg-surface-1) !important;
    background-image: none !important;
    color: var(--hg-ink) !important;
    border-color: var(--hg-border-resting) !important;
  }
  .s-item__title, .s-item__price, .x-item-title__mainTitle,
  .x-price-primary span, [class*="price"], [class*="Price"],
  [class*="s-card__title"], [class*="s-card__price"] {
    color: var(--hg-ink-bright) !important;
  }
  .s-item__title a, .s-item__link, .s-item__title a:hover,
  [class*="s-card"] a, [class*="su-card"] a {
    color: var(--hg-accent-soft) !important;
  }
  .s-item__shipping, .s-item__location, .s-item__subtitle,
  .s-item__seller-info-text, [class*="secondary"], [class*="muted"],
  [class*="s-card__caption"], [class*="s-card__subtitle"],
  [class*="s-card__attribute"] {
    color: var(--hg-ink-dim) !important;
  }
  /* Generic text spans used throughout both markup generations: inherit
     the card's text color instead of staying at eBay's own default,
     which is often a near-black meant for a white card. */
  [class*="card"] [class*="textspans"],
  [class*="s-card"] [class*="textspans"],
  [class*="su-card"] [class*="textspans"],
  .s-item [class*="textspans"] {
    color: inherit !important;
  }

  /* ----------------------------------------------------------------------
     UX-TEXTSPANS — the wrapper eBay puts almost EVERY piece of body text
     in, on the item detail page (price, condition, shipping, seller name,
     "Hurry before it's gone", payment methods, and so on). Confirmed from
     inspected markup that eBay's own class is written in upper case
     ("ux-textspans--SECONDARY", "--BOLD", "--PSEUDOLINK"), not the lower
     case this theme originally guessed — CSS class matching is case
     sensitive, so the earlier rules silently matched nothing and these
     spans were showing eBay's own near-black default color on our dark
     panels. This is likely the single biggest reason the item page read
     as "unthemed" next to the homepage. ---------------------------------- */
  html body .ux-textspans {
    color: inherit !important;
  }
  html body .ux-textspans--BOLD {
    color: var(--hg-ink-bright) !important;
  }
  html body .ux-textspans--SECONDARY {
    color: var(--hg-ink-dim) !important;
  }
  html body .ux-textspans--PSEUDOLINK,
  html body .ux-textspans--LEGAL_LINK {
    color: var(--hg-accent-soft) !important;
  }
  html body a:hover .ux-textspans--PSEUDOLINK,
  html body button:hover .ux-textspans--PSEUDOLINK,
  html body .fake-link:hover .ux-textspans--PSEUDOLINK {
    color: var(--hg-accent-strong) !important;
  }
  html body .ux-textspans--SUPERSCRIPT {
    color: inherit !important;
  }

  /* Tooltips/infotips (ⓘ popovers) and lightbox dialogs: same glass
     treatment as the other overlay surfaces, since neither "lightbox-
     dialog" nor "infotip__overlay" contains the word modal/popover that
     the earlier generic rule matched on. */
  html body .infotip__overlay,
  html body [role="tooltip"],
  html body .lightbox-dialog,
  html body .lightbox-dialog__window {
    background: var(--hg-glass-bg) !important;
    color: var(--hg-ink-bright) !important;
    border: 1px solid rgba(101,255,148,.45) !important;
    box-shadow: var(--hg-glow-md) !important;
    -webkit-backdrop-filter: var(--hg-glass-blur) !important;
    backdrop-filter: var(--hg-glass-blur) !important;
  }
  html body .infotip__pointer { display: none !important; }

  /* Klarna / financing promo banners: give the pill module a panel fill
     instead of leaving its native light background in place. */
  html body .promotional-spotlight,
  html body [class*="financing-details"],
  html body [class*="financing-options-section"] {
    background-color: rgba(13,32,20,.5) !important;
    color: var(--hg-ink) !important;
    border-color: rgba(101,255,148,.35) !important;
  }
  html body .d-financing-options-section__step-badge .badge {
    background-color: var(--hg-accent-cta) !important;
    color: #f5fff7 !important;
  }

  /* Cards/tiles hover: quiet border brighten, no heavy stacked glow */
  html body .s-item:hover,
  html body [class*="card"]:hover,
  html body [class*="Card"]:hover,
  html body [class*="tile"]:hover,
  html body [class*="Tile"]:hover,
  html body [class*="s-card"]:hover,
  html body [class*="su-card"]:hover,
